#include <omp.h>
#include <array>
#include <vector>
#include <cstddef>

void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {
    bins.fill(0);

    const int max_threads = omp_get_max_threads();
    std::vector<std::array<size_t, 256>> thread_bins(static_cast<std::size_t>(max_threads));
    for (auto &local : thread_bins) {
        local.fill(0);
    }

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto &local = thread_bins[static_cast<std::size_t>(tid)];

        #pragma omp for schedule(static)
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(image.size()); ++i) {
            const int value = image[static_cast<std::size_t>(i)];
            if (value >= 0 && value < 256) {
                ++local[static_cast<std::size_t>(value)];
            }
        }
    }

    for (const auto &local : thread_bins) {
        for (std::size_t v = 0; v < 256; ++v) {
            bins[v] += local[v];
        }
    }
}
